import os
import posixpath

def _t():

    def check(paths, expected):
        assert posixpath.commonpath(paths) == expected, ('assertEqual', posixpath.commonpath(paths), expected)
        assert posixpath.commonpath([os.fsencode(p) for p in paths]) == os.fsencode(expected), ('assertEqual', posixpath.commonpath([os.fsencode(p) for p in paths]), os.fsencode(expected))

    def check_error(exc, paths):
        try:
            posixpath.commonpath(*(paths,))
        except exc:
            pass
        try:
            posixpath.commonpath(*([os.fsencode(p) for p in paths],))
        except exc:
            pass
    try:
        posixpath.commonpath(*(None,))
    except TypeError:
        pass
    try:
        posixpath.commonpath(*([],))
    except ValueError:
        pass
    try:
        posixpath.commonpath(*(iter([]),))
    except ValueError:
        pass
    check_error(ValueError, ['/usr', 'usr'])
    check_error(ValueError, ['usr', '/usr'])
    check(['/usr/local'], '/usr/local')
    check(['/usr/local', '/usr/local'], '/usr/local')
    check(['/usr/local/', '/usr/local'], '/usr/local')
    check(['/usr/local/', '/usr/local/'], '/usr/local')
    check(['/usr//local', '//usr/local'], '/usr/local')
    check(['/usr/./local', '/./usr/local'], '/usr/local')
    check(['/', '/dev'], '/')
    check(['/usr', '/dev'], '/')
    check(['/usr/lib/', '/usr/lib/python3'], '/usr/lib')
    check(['/usr/lib/', '/usr/lib64/'], '/usr')
    check(['/usr/lib', '/usr/lib64'], '/usr')
    check(['/usr/lib/', '/usr/lib64'], '/usr')
    check(['spam'], 'spam')
    check(['spam', 'spam'], 'spam')
    check(['spam', 'alot'], '')
    check(['and/jam', 'and/spam'], 'and')
    check(['and//jam', 'and/spam//'], 'and')
    check(['and/./jam', './and/spam'], 'and')
    check(['and/jam', 'and/spam', 'alot'], '')
    check(['and/jam', 'and/spam', 'and'], 'and')
    check([''], '')
    check(['', 'spam/alot'], '')
    check_error(ValueError, ['', '/spam/alot'])
    try:
        posixpath.commonpath(*([b'/usr/lib/', '/usr/lib/python3'],))
    except TypeError:
        pass
    try:
        posixpath.commonpath(*([b'/usr/lib/', 'usr/lib/python3'],))
    except TypeError:
        pass
    try:
        posixpath.commonpath(*([b'usr/lib/', '/usr/lib/python3'],))
    except TypeError:
        pass
    try:
        posixpath.commonpath(*(['/usr/lib/', b'/usr/lib/python3'],))
    except TypeError:
        pass
    try:
        posixpath.commonpath(*(['/usr/lib/', b'usr/lib/python3'],))
    except TypeError:
        pass
    try:
        posixpath.commonpath(*(['usr/lib/', b'/usr/lib/python3'],))
    except TypeError:
        pass
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')
